rss.channel:
{{ .Repo.Title }}
{{ .URL }}/repoview/latest-feed.xml
Latest packages for {{ .Repo.Title }}
{{ now | rssTime }}
RepoView-Go
{{ range .Latest }}


  {{ $.URL }}/repoview/{{ .Filename }}+{{ if .Epoch }}{{ .Epoch }}{{ else }}0{{ end }}:{{ .Version }}-{{ .Release }}.{{ .Arch }}
  {{ $.URL }}/repoview/{{ .Filename }}
  {{ .TimeBuild | rssTime }}
  Update: {{ .Name }}-{{ .Version }}-{{ .Release }}

    <p>
      <strong>Package:</strong> {{ .Name }}<br/>
      <strong>Summary:</strong> {{ .Summary }}
    </p>
    <p>
      <strong>Description:</strong><br/>
      {{ .Description }}
    </p>
    <h3>Changes:</h3>
    <table border="0" cellpadding="0" cellspacing="5">
    {{ range .AllVersions }}
      <tr>
        <td valign="top"><a href="{{ $.URL }}/{{ .LocationHref }}">{{ .Name }}-{{ .Version }}-{{ .Release }}.{{ .Arch }}</a>
          [<span style="white-space: nowrap">{{ .SizePackage | humanSize }}</span>]</td>
        {{ if .Changelog }}
        <td valign="top">
          <strong>Changelog</strong>
          by <span>{{ .Changelog.Author }} ({{ .Changelog.Date | ymd }})</span>:
          <pre style="margin: 0pt 0pt 5pt 5pt">{{ .Changelog.Changelog }}</pre>
        </td>
        {{ else }}
        <td valign="top">
          <em>(no changelog entry)</em>
        </td>
        {{ end }}
      </tr>
    {{ end }}
    </table>


{{ end }}
